solution.javascript:
const fs = require('fs');

function main() {
    const s = fs.readFileSync(0, 'utf-8').trim();
    if (s.length > 0) {
        const n = parseInt(s, 10);
        const rem = n % 3;
        if (rem === 0) console.log("The number is divisible by 3");
        else console.log(`The number is not divisible by 3 and gives a remainder ${rem}`);
    }
}

main();

