const fs = require('fs');

function main() {
    const s = fs.readFileSync(0, 'utf-8').trim();
    if (s.length > 0) {
        const n = parseInt(s, 10);
        if (n % 15 === 0) console.log("HiHello");
        else if (n % 3 === 0) console.log("Hi");
        else if (n % 5 === 0) console.log("Hello");
    }
}

main();
